-- Season parking database. Run: mysql -u root -p < parking.sql
CREATE DATABASE IF NOT EXISTS parking CHARACTER SET utf8mb4;
USE parking;
DROP TABLE IF EXISTS places; DROP TABLE IF EXISTS sold_carparks; DROP TABLE IF EXISTS lta_carpark_rates;
CREATE TABLE places(
 id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, area VARCHAR(60), type ENUM('Mall','Office','Venue'),
 season_price_car DECIMAL(8,2) NULL, price_note VARCHAR(200), capacity_lots INT NULL, capacity_as_at VARCHAR(40),
 contact VARCHAR(300), source_name VARCHAR(80), source_url VARCHAR(500),
 capacity_source_name VARCHAR(80), capacity_source_url VARCHAR(500), INDEX(area), INDEX(type));
CREATE TABLE sold_carparks(id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120), spaces INT, price_text VARCHAR(80), price_per_space INT, source_url VARCHAR(500));
CREATE TABLE lta_carpark_rates(id INT PRIMARY KEY, carpark VARCHAR(160), category VARCHAR(60), weekdays_rate_1 TEXT, weekdays_rate_2 TEXT, saturday_rate TEXT, sunday_ph_rate TEXT,
 source_url VARCHAR(200) DEFAULT 'https://data.gov.sg/datasets/d_9f6056bdb6b1dfba57f063593e4f34ae/view', INDEX(category));
